nt->>'schema_version'IS DISTINCT FROM 'cure-command-amendment/1'OR coalesce(amendment->>'state','')NOT IN('active_amendment','inert_recovery')\n OR amendment->>'active_repair_kind'IS DISTINCT FROM 'cure-reaction-turn/1'\n OR amendment->>'commit_source_md5'IS DISTINCT FROM '61532836e90ed32ae807b92ee6632b71'\n OR amendment->>'normalized_source_identity_sha256'IS DISTINCT FROM 'e00efa15142faaa8c07767231e969224273f43b838e733b9a61d70f1e326bc2b'\n OR public.combat_v2_sha256(amendment->'normalized_source_identity')IS DISTINCT FROM amendment->>'normalized_source_identity_sha256'\n OR amendment->>'base_catalogo_source_bundle_sha256'IS DISTINCT FROM '825a1c14a59281fb3168430a993e9f2dbbbc41042f5169638d2e9c1e8e9868a5'\n"},{"before":" relations_sha:=public.combat_v2_sha256(jsonb_build_object('relations',relation_manifest,'triggers',trigger_manifest));\n\n IF shared_sha IS DISTINCT FROM root#>>'{db_core,catalogo_completo,shared_manifest_sha256}'\n OR private_sha IS DISTINCT FROM amendment->>'private_functions_manifest_sha256'\n OR relations_sha IS DISTINCT FROM root#>>'{db_core,catalogo_completo,relations_manifest_sha256}'\n","after":" relations_sha:=public.combat_v2_sha256(jsonb_build_object('relations',relation_manifest,'triggers',trigger_manifest));\n\n IF shared_sha IS DISTINCT FROM amendment->>'shared_manifest_sha256'\n OR private_sha IS DISTINCT FROM amendment->>'private_functions_manifest_sha256'\n OR relations_sha IS DISTINCT FROM root#>>'{db_core,catalogo_completo,relations_manifest_sha256}'\n"},{"before":" OR relations_sha IS DISTINCT FROM binding->>'relations_manifest_sha256'\n THEN RAISE EXCEPTION 'catalogo_eligibility_integrated_manifest_drift';END IF;\n RETURN true;\nEND $function$\n","after":" OR relations_sha IS DISTINCT FROM binding->>'relations_manifest_sha256'\n THEN RAISE EXCEPTION 'catalogo_eligibility_integrated_manifest_drift';END IF;\n\n -- Three owning substitution ports, exact bodies/ABI; authority stays native.\n FOR item IN SELECT value FROM jsonb_array_elements(params->'native_functions')ORDER BY value->>'signature'LOOP\n  SELECT jsonb_build_object('signature',p.oid::regprocedure::text,'source_md5',md5(p.prosrc),'ddl_md5',md5(pg_get_functiondef(p.oid)),\n   'owner',pg_get_userbyid(p.proowner),'acl',p.proacl::text,'config',p.proconfig,'secdef',p.prosecdef,'volatility',p.provolatile::text,\n   'language',l.lanname,'strict',p.proisstrict,'parallel',p.proparallel::text,'returns',pg_get_function_result(p.oid),\n   'arg_names',p.proargnames,'arg_modes',p.proargmodes,'arg_types',p.proargtypes::text)INTO h\n   FROM pg_proc p JOIN pg_language l ON l.oid=p.prolang WHERE p.oid=to_regprocedure(item->>'signature')AND p.prokind='f';\n  IF h IS DISTINCT FROM item THEN RAISE EXCEPTION 'cure_reaction_native_body_or_abi_drift:%',item->>'signature';END IF;\n  native_manifest:=native_manifest||jsonb_build_array(h);\n END LOOP;\n IF jsonb_array_length(native_manifest)<>3 OR public.combat_v2_sha256(native_manifest)IS DISTINCT FROM amendment->>'native_functions_manifest_sha256'\n THEN RAISE EXCEPTION 'cure_reaction_native_manifest_drift';END IF;\n -- Own helper metadata is bound externally by the reviewed Root, never a literal self hash.\n SELECT jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'source_md5',md5(p.prosrc),'ddl_md5',md5(pg_get_functiondef(p.oid)),\n  'owner',pg_get_userbyid(p.proowner),'secdef',p.prosecdef,'config',p.proconfig,'acl',p.proacl::text,'volatility',p.provolatile::text)\n  ORDER BY p.oid::regprocedure::text)INTO changed_manifest FROM pg_proc p WHERE p.oid IN(\n  'combat_panel_private.round_options_authoritative(uuid,uuid)'::regprocedure,\n  'public.combat_v2_substitution_options_v1(uuid)'::regprocedure,'public.combat_v2_substitution_round_offers_v1(uuid,uuid)'::regprocedure,\n  'public.combat_v2_substitution_select_v1(uuid,uuid)'::regprocedure,'clan_innata_private.catalogo_eligibility_release_v1()'::regprocedure);\n IF jsonb_array_length(changed_manifest)<>5 OR public.combat_v2_sha256(changed_manifest)IS DISTINCT FROM amendment->>'functions_manifest_sha256'\n THEN RAISE EXCEPTION 'cure_reaction_changed_manifest_drift';END IF;\n RETURN true;\nEND $function$\n"}]}]$cure_hunks$::jsonb;p jsonb;h jsonb;s text;actual text;
BEGIN
 FOR p IN SELECT value FROM jsonb_array_elements(ps)LOOP
  s:=pg_get_functiondef(to_regprocedure(p->>'signature'));
  IF s IS NULL OR encode(extensions.digest(convert_to(s,'UTF8'),'sha256'),'hex')IS DISTINCT FROM p->>'before_ddl_sha256'
  THEN RAISE EXCEPTION 'cure_reaction_patch_preimage:%',p->>'signature';END IF;
 END LOOP;
 FOR p IN SELECT value FROM jsonb_array_elements(ps)LOOP
  s:=pg_get_functiondef(to_regprocedure(p->>'signature'));
  FOR h IN SELECT value FROM jsonb_array_elements(p->'hunks')LOOP
   IF length(h->>'before')=0 OR(length(s)-length(replace(s,h->>'before','')))/length(h->>'before')<>1
   THEN RAISE EXCEPTION 'cure_reaction_patch_anchor:%',p->>'signature';END IF;
   s:=replace(s,h->>'before',h->>'after');
  END LOOP;
  IF encode(extensions.digest(convert_to(s,'UTF8'),'sha256'),'hex')IS DISTINCT FROM p->>'after_ddl_sha256'THEN RAISE EXCEPTION 'cure_reaction_patch_composition';END IF;
  EXECUTE s;
  SELECT prosrc INTO STRICT actual FROM pg_proc WHERE oid=to_regprocedure(p->>'signature');
  IF md5(actual)IS DISTINCT FROM p->>'after_source_md5'OR encode(extensions.digest(convert_to(pg_get_functiondef(to_regprocedure(p->>'signature')),'UTF8'),'sha256'),'hex')IS DISTINCT FROM p->>'after_ddl_sha256'
  THEN RAISE EXCEPTION 'cure_reaction_patch_postimage:%',p->>'signature';END IF;
 END LOOP;
END $cure_reaction_patch$;
-- SOURCE ONLY · current reaction amendment; four owning deltas and closed helper precede this forward Root.
-- Base825a/compat654f/commandE14/neutral0780 remain provenance; current manifest is amended explicitly.
-- Congelare app.cure_reaction_parameters e finalizzare il pin dopo review pertinente della capsule.
DO $catalogo_root$
DECLARE
 expected_parameters_sha256 constant text:='__CURE_REACTION_PARAMETERS_SHA256__';
 old_root_sha constant text:='79f17709193ac47f564f18cde1114cceefe099cd2c646b6f0b2306b93d28ca0d';
